class Solution {
  public int[] gcdValues(int[] nums, long[] queries) {
    int max = 0;
    for (int x : nums) max = Math.max(max, x);
    long[] cnt = new long[max + 1];
    for (int x : nums) cnt[x]++;
    long[] exact = new long[max + 1];
    for (int g = max; g >= 1; g--) {
      long c = 0;
      for (int m = g; m <= max; m += g) c += cnt[m];
      long pairs = c * (c - 1) / 2;
      for (int m = 2 * g; m <= max; m += g) pairs -= exact[m];
      exact[g] = pairs;
    }
    for (int g = 2; g <= max; g++) exact[g] += exact[g - 1];
    int[] ans = new int[queries.length];
    for (int i = 0; i < queries.length; i++) {
      int lo = 1, hi = max;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (exact[mid] > queries[i]) hi = mid;
        else lo = mid + 1;
      }
      ans[i] = lo;
    }
    return ans;
  }
}
